mod error;

use std::collections::HashSet;
use std::ffi::OsStr;
use std::fs;
use std::io::{BufRead, BufReader, ErrorKind, Read};
use std::path::{Path, PathBuf};

use crate::Warning;
pub use error::WriteError;

/// The words that open the first line of every generated file, after the
/// comment sign.
pub(crate) const MARKER: &str = "@generated by refix codegen";

/// A generated package and any [`Warning`] produced along the way.
#[derive(Debug)]
pub struct Package {
    pub modules: Vec<Module>,
    pub warnings: Vec<Warning>,
    /// Every directory a run can write into, relative to the package's.
    directories: Vec<PathBuf>,
}

/// One file of a generated [`Package`].
#[derive(Debug, Eq, PartialEq)]
pub struct Module {
    /// Where the file goes, relative to the package's directory.
    pub path: PathBuf,
    pub code: String,
}

impl Package {
    pub(crate) fn new(modules: Vec<Module>, warnings: Vec<Warning>, directories: &[&str]) -> Self {
        Self {
            modules,
            warnings,
            directories: directories.iter().map(PathBuf::from).collect(),
        }
    }

    /// Writes the package's files into `directory`, creating it as needed.
    ///
    /// A generated file an earlier run left there is removed when this run
    /// did not write it. Any other file is left alone, generated code in
    /// another language included.
    pub fn write(&self, directory: &Path) -> Result<(), WriteError> {
        for module in &self.modules {
            let path = directory.join(&module.path);
            if let Some(parent) = path.parent() {
                fs::create_dir_all(parent)
                    .map_err(|source| WriteError::new("create", parent, source))?;
            }
            fs::write(&path, &module.code)
                .map_err(|source| WriteError::new("write", &path, source))?;
        }
        let written: HashSet<&Path> = self
            .modules
            .iter()
            .map(|module| module.path.as_path())
            .collect();
        let extensions: HashSet<&OsStr> =
            written.iter().filter_map(|path| path.extension()).collect();
        for relative in &self.directories {
            remove_leftovers(directory, relative, &written, &extensions)?;
        }
        Ok(())
    }
}

/// Removes the generated files in one of the package's directories that
/// are not among `written` and have one of its `extensions`.
fn remove_leftovers(
    directory: &Path,
    relative: &Path,
    written: &HashSet<&Path>,
    extensions: &HashSet<&OsStr>,
) -> Result<(), WriteError> {
    let folder = directory.join(relative);
    let entries = match fs::read_dir(&folder) {
        Ok(entries) => entries,
        // No run has written into it yet.
        Err(error) if error.kind() == ErrorKind::NotFound => return Ok(()),
        Err(source) => return Err(WriteError::new("read", &folder, source)),
    };
    for entry in entries {
        let entry = entry.map_err(|source| WriteError::new("read", &folder, source))?;
        if written.contains(relative.join(entry.file_name()).as_path()) {
            continue;
        }
        let path = entry.path();
        let in_this_language = path
            .extension()
            .is_some_and(|extension| extensions.contains(extension));
        if in_this_language && is_generated(&path) {
            fs::remove_file(&path).map_err(|source| WriteError::new("remove", &path, source))?;
        }
    }
    Ok(())
}

/// Whether the file at `path` opens with a generated file's first line.
fn is_generated(path: &Path) -> bool {
    let Ok(file) = fs::File::open(path) else {
        return false;
    };
    let mut first_line = String::new();
    // A directory or a file that is not text cannot be read as a line.
    if BufReader::new(file.take(256))
        .read_line(&mut first_line)
        .is_err()
    {
        return false;
    }
    first_line
        .trim_start_matches(['#', '/', ' '])
        .starts_with(MARKER)
}

#[cfg(test)]
mod tests {
    use std::path::{Path, PathBuf};
    use std::sync::atomic::{AtomicUsize, Ordering};

    use super::{Module, Package};

    /// A fresh directory for one test's files.
    fn scratch_directory() -> PathBuf {
        static RUNS: AtomicUsize = AtomicUsize::new(0);
        let run = RUNS.fetch_add(1, Ordering::Relaxed);
        let name = format!("refix-codegen-{}-{run}", std::process::id());
        let directory = std::env::temp_dir().join(name);
        std::fs::create_dir_all(&directory).unwrap();
        directory
    }

    fn package(paths: &[&str]) -> Package {
        let modules = paths
            .iter()
            .map(|path| Module {
                path: PathBuf::from(path),
                code: format!(
                    "# @generated by refix codegen from toy.xml. Do not edit.\n# {path}\n"
                ),
            })
            .collect();
        Package::new(modules, vec![], &["", "messages"])
    }

    fn files(directory: &Path) -> Vec<String> {
        let mut files = Vec::new();
        for folder in ["", "messages", "notes"] {
            let Ok(entries) = std::fs::read_dir(directory.join(folder)) else {
                continue;
            };
            for entry in entries {
                let entry = entry.unwrap();
                if entry.file_type().unwrap().is_file() {
                    let name = Path::new(folder).join(entry.file_name());
                    files.push(name.to_str().unwrap().to_owned());
                }
            }
        }
        files.sort();
        files
    }

    #[test]
    fn writes_each_module_at_its_path() {
        let directory = scratch_directory();

        package(&["__init__.py", "messages/logon.py"])
            .write(&directory.join("toy"))
            .unwrap();

        let logon = std::fs::read_to_string(directory.join("toy/messages/logon.py")).unwrap();
        assert_eq!(
            files(&directory.join("toy")),
            ["__init__.py", "messages/logon.py"]
        );
        assert!(logon.ends_with("# messages/logon.py\n"));
        std::fs::remove_dir_all(&directory).unwrap();
    }

    #[test]
    fn removes_a_generated_file_a_later_run_does_not_write() {
        let directory = scratch_directory();
        package(&[
            "__init__.py",
            "old.py",
            "messages/logon.py",
            "messages/quote.py",
        ])
        .write(&directory)
        .unwrap();

        package(&["__init__.py", "messages/logon.py"])
            .write(&directory)
            .unwrap();

        assert_eq!(files(&directory), ["__init__.py", "messages/logon.py"]);
        std::fs::remove_dir_all(&directory).unwrap();
    }

    #[test]
    fn removes_the_generated_files_of_a_directory_left_unused() {
        let directory = scratch_directory();
        package(&["__init__.py", "messages/logon.py"])
            .write(&directory)
            .unwrap();

        package(&["__init__.py"]).write(&directory).unwrap();

        assert_eq!(files(&directory), ["__init__.py"]);
        std::fs::remove_dir_all(&directory).unwrap();
    }

    #[test]
    fn leaves_a_file_without_the_first_line_alone() {
        let directory = scratch_directory();
        std::fs::create_dir_all(directory.join("messages")).unwrap();
        std::fs::write(directory.join("py.typed"), "").unwrap();
        std::fs::write(directory.join("messages/mine.py"), "# My own.\n").unwrap();
        std::fs::write(directory.join("messages/data.bin"), [0xff, 0xfe]).unwrap();

        package(&["__init__.py"]).write(&directory).unwrap();

        assert_eq!(
            files(&directory),
            [
                "__init__.py",
                "messages/data.bin",
                "messages/mine.py",
                "py.typed"
            ]
        );
        std::fs::remove_dir_all(&directory).unwrap();
    }

    #[test]
    fn leaves_a_generated_file_in_another_language_alone() {
        let directory = scratch_directory();
        let rust = "// @generated by refix codegen from toy.xml. Do not edit.\n";
        std::fs::write(directory.join("mod.rs"), rust).unwrap();

        package(&["__init__.py"]).write(&directory).unwrap();

        assert_eq!(files(&directory), ["__init__.py", "mod.rs"]);
        std::fs::remove_dir_all(&directory).unwrap();
    }

    #[test]
    fn leaves_a_generated_file_in_another_directory_alone() {
        let directory = scratch_directory();
        std::fs::create_dir_all(directory.join("notes")).unwrap();
        let generated = "// @generated by refix codegen from toy.xml. Do not edit.\n";
        std::fs::write(directory.join("notes/other.rs"), generated).unwrap();

        package(&["__init__.py"]).write(&directory).unwrap();

        assert_eq!(files(&directory), ["__init__.py", "notes/other.rs"]);
        std::fs::remove_dir_all(&directory).unwrap();
    }

    #[test]
    fn a_file_in_the_way_of_a_directory_is_an_error() {
        let directory = scratch_directory();
        std::fs::write(directory.join("messages"), "").unwrap();

        let error = package(&["messages/logon.py"])
            .write(&directory)
            .unwrap_err();

        let message = error.to_string();
        assert!(message.starts_with("cannot create '"));
        assert!(message.contains("messages': "));
        std::fs::remove_dir_all(&directory).unwrap();
    }
}
